      checkpointId: null,
      includedCheckpoints: [],
      checkpointSelectionMode: 'latest',
      effectiveLastCheckpoints: 1,
      checkpointReady: false,
      checkpointDetail: `${buildMissingCheckpointTrailerMessage(
