  try {
    const diff = await getWorkspaceDiffForUiProxy(workerUrl, session.workspaceId, {
      includePatch: options?.includePatch,
      ...(typeof options?.maxBytes === 'number' ? { maxBytes: options.maxBytes } : {}),
