      reason: hasDiff ? null : 'Nimbus has no reviewed diff content to show for this session.',
      path,
      environmentRevision,
      ...(hasDiff ? { diff } : {}),
    };
  } catch (error) {
    return {
      sessionId: session.id,
      reviewId: session.latestReviewId,
      available: false,
      status: 'error',
      reason: error instanceof Error ? error.message : String(error),
      path,
      environmentRevision,
    };
  }
}

