      setError(null);
    } catch (loadError) {
      if (!background || !hasLoadedHomeRef.current) {
        setError(loadError instanceof Error ? loadError.message : String(loadError));
      }
    } finally {
      if (!background) {
        setLoading(false);
      }
    }
  }, []);

