442	  onEvent?: (event: StudioNewReviewStartStreamEvent) => void | Promise<void>;
443	}): Promise<StudioNewReviewStartResult> {
444	  let abortBeforeReviewCreation = true;
445	  const throwIfAborted = (): void => {
446	    if (!shouldAbortStudioStart(options.signal, abortBeforeReviewCreation)) {
447	      return;
448	    }
449	    const error = new Error('Studio review start aborted before completion.');
450	    error.name = 'AbortError';
451	    throw error;
452	  };
453	  const emitEvent = async (event: StudioNewReviewStartStreamEvent): Promise<void> => {
454	    throwIfAborted();
455	    try {
456	      await options.onEvent?.(event);
457	    } catch {
458	      // Start-flow events are best-effort only and must not abort review setup.
459	    }
460	  };
461	
462	  throwIfAborted();
463	  const policyMode = normalizeStudioPolicyMode(options.policyMode);
464	  const lastCheckpoints = normalizeLastCheckpoints(options.lastCheckpoints ?? null);
465	  const repoRoot = resolveStudioRepoRoot(options.repoRoot);
466	  const workerUrl = getWorkerUrl();
467	  if (!workerUrl) {
468	    throw new Error('NIMBUS_WORKER_URL environment variable is required');
469	  }
470	
471	  const gitProvenance = resolveReviewGitProvenance(repoRoot);
472	  if (
473	    !studioBranchContextMatchesExpected(gitProvenance, {
474	      repo: options.expectedRepo,
475	      branch: options.expectedBranch,
476	    })
477	  ) {
478	    throw new Error(
479	      `Studio context changed to ${gitProvenance.branch} (${gitProvenance.repo}). Switch context in Home, then retry.`
480	    );
481	  }
482	
483	  await updateStudioPolicyMode(policyMode, { repoRoot });
484	  const checkpointWindow = resolveStudioCheckpointWindow(repoRoot, lastCheckpoints);
485	  const resolved = await resolveReviewContext({
486	    commitish: 'HEAD',
487	    projectRoot: '.',
488	    lastCheckpoints: checkpointWindow.effectiveLastCheckpoints,
489	    signal: options.signal,
490	    onProgress: (event) => emitEvent({
491	      type: 'stage',
492	      stage: event.stage,
493	      state: event.state,
494	      label: event.label,
495	      detail: event.detail,
496	    }),
497	  });
498	  // Once context setup produced a workspace/deployment, finish attaching it to a
499	  // review instead of aborting and leaving startup artifacts unattached.
500	  abortBeforeReviewCreation = false;
501	
502	  await emitEvent({
503	    type: 'stage',
504	    stage: 'review_creation',
505	    state: 'active',
506	    label: policyMode === 'review' ? 'Creating policy review' : 'Creating review',
507	    detail:
508	      policyMode === 'review'
509	        ? 'Creating the review and opening the Review Run route.'
510	        : 'Creating the review record before queueing analysis.',
511	  });
512	
513	  if (policyMode === 'review') {
514	    throwIfAborted();
515	    const derived = await deriveReviewPolicy(workerUrl, {
516	      workspaceId: resolved.workspaceId,
517	      deploymentId: resolved.deploymentId,
518	      policyMode: 'review',
519	      reviewBasis: 'checkpoint',
520	      provenance: resolved.resolvedProvenance,
521	    });
522	    // Once the review exists, finish the handoff even if the client disconnects.
523	    abortBeforeReviewCreation = false;
524	
525	    await emitEvent({
526	      type: 'stage',
527	      stage: 'review_creation',
528	      state: 'completed',
529	      label: 'Policy review ready',
530	      detail: `Review ${derived.reviewId} is ready for policy confirmation.`,
531	    });
532	
533	    const result: StudioNewReviewStartResult = {
534	      reviewId: derived.reviewId,
535	      sessionId: derived.sessionId ?? null,
536	      routePath: derived.sessionId
537	        ? buildStudioSessionRoutePath({
538	            sessionId: derived.sessionId,
539	            reviewId: derived.reviewId,
540	            repo: resolved.resolvedProvenance.repo,
541	            branch: resolved.resolvedProvenance.branch,
542	          })
543	        : buildStudioReviewRoutePath({
544	            reviewId: derived.reviewId,
545	            route: 'reports',
546	            repo: resolved.resolvedProvenance.repo,
547	            branch: resolved.resolvedProvenance.branch,
548	          }),
549	      policyMode,
550	      contextMode: resolved.resolvedProvenance.reviewContextMode === 'intent_aware' ? 'intent_aware' : 'basic',
551	      requestedLastCheckpoints: lastCheckpoints,
552	      effectiveLastCheckpoints: checkpointWindow.effectiveLastCheckpoints,
553	      status: 'policy_ready',
554	    };
555	    await emitEvent({
556	      type: 'completed',
557	      ...result,
558	      detail: 'Policy review is ready. Opening the Review Run route.',
559	    });
560	    return result;
561	  }
562	
563	  throwIfAborted();
564	  const derived = await deriveReviewPolicy(workerUrl, {
565	    workspaceId: resolved.workspaceId,
566	    deploymentId: resolved.deploymentId,
567	    policyMode: 'auto',
568	    reviewBasis: 'checkpoint',
569	    provenance: resolved.resolvedProvenance,
