  gap: 0.65rem;
}

.launch-fact {
  padding: 0.78rem 0.84rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: rgba(248, 250, 252, 0.92);
}

.launch-fact span,
.launch-check-state,
.launch-status,
.launch-code {
  font-family: var(--font-code);
}

.launch-fact span {
  display: block;
