import { AnimatePresence, motion, useReducedMotion } from 'framer-motion';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Navigate, useNavigate } from 'react-router-dom';
import {
  parseListReviewSessionsResponse,
  parseStudioContextResponse,
  parseStudioNewReviewPreflightResponse,
  parseStudioNewReviewStartStreamEvent,
} from '../lib/review';
import type {
  ReviewSessionResponse,
  StudioContextResponse,
  StudioNewReviewPreflightResponse,
  StudioNewReviewStartStageEvent,
} from '../types';

const API_BASE = (import.meta.env.VITE_NIMBUS_API_BASE_URL as string | undefined)?.replace(/\/$/, '') ?? '';
const STUDIO_MOCK_ENABLED = ['1', 'true', 'yes', 'on'].includes(
  ((import.meta.env.VITE_STUDIO_MOCK as string | undefined) ?? '').trim().toLowerCase()
);
const ENTIRE_DOCS_URL = 'https://github.com/dayhaysoos/nimbus/blob/main/docs/entire/recovery.md';
const LAST_CHECKPOINTS = 1;
const HOME_REFRESH_INTERVAL_MS = 3_000;
const MOCK_REPO = 'dayhaysoos/nimbus';
const MOCK_BRANCH = 'codex/studio-launch-rebuild';
const MOCK_COMMIT_SHA = '4f8c2be';

type MockStudioState = 'ready' | 'basic' | 'blocked' | 'no_repo';

interface StartStageState {
  stage: StudioNewReviewStartStageEvent['stage'];
  label: string;
  detail: string;
  state: 'active' | 'completed';
}

type LaunchState = 'checking' | 'ready' | 'basic' | 'blocked' | 'starting';

function resolveMockStudioState(): MockStudioState {
  const raw = ((import.meta.env.VITE_STUDIO_MOCK_STATE as string | undefined) ?? '').trim().toLowerCase();
  if (raw === 'basic' || raw === 'blocked' || raw === 'no_repo') {
    return raw;
  }
  return 'ready';
}

function createMockStudioContext(): StudioContextResponse | null {
  const detectedAt = new Date().toISOString();
  if (resolveMockStudioState() === 'no_repo') {
    return {
      repo: null,
      branch: null,
      detectedAt,
    };
  }
  return {
    repo: MOCK_REPO,
    branch: MOCK_BRANCH,
    detectedAt,
  };
}

function createMockPreflight(): StudioNewReviewPreflightResponse | null {
  const state = resolveMockStudioState();
  if (state === 'no_repo') {
    return null;
  }

  const detectedAt = new Date().toISOString();
  const common = {
    repo: MOCK_REPO,
    branch: MOCK_BRANCH,
    policyMode: 'auto' as const,
    requestedLastCheckpoints: LAST_CHECKPOINTS as 1,
    effectiveLastCheckpoints: LAST_CHECKPOINTS as 1,
    lastCheckpoints: LAST_CHECKPOINTS as 1,
    checkpointSelectionMode: 'latest' as const,
    commitSha: MOCK_COMMIT_SHA,
    includedCheckpoints: [
      {
        checkpointId: 'checkpoint_mock_ready',
        commitSha: MOCK_COMMIT_SHA,
        commitSubject: 'Rebuild Studio launch experience',
      },
    ],
  };

  if (state === 'basic') {
    return {
      ...common,
      startability: 'basic',
      contextMode: 'basic',
      checkpointId: 'checkpoint_mock_ready',
      ready: true,
      capabilities: {
        canStart: true,
        canStartInBasicMode: true,
        canStartInIntentAwareMode: false,
        canReviewPolicy: false,
      },
      blockingIssues: [],
      warnings: [
        {
          code: 'entire_context_unavailable',
          message: 'Entire context was not found for the current checkpoint window.',
        },
      ],
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint',
          ok: true,
          detail: 'A checkpoint is available for the current commit.',
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: 'Entire context is unavailable, so Nimbus will fall back to basic review mode.',
        },
      ],
    };
  }

  if (state === 'blocked') {
    return {
      ...common,
      startability: 'blocked',
      contextMode: 'basic',
      checkpointId: null,
      ready: false,
      capabilities: {
        canStart: false,
        canStartInBasicMode: false,
        canStartInIntentAwareMode: false,
        canReviewPolicy: false,
      },
      blockingIssues: [
        {
          code: 'checkpoint_unavailable',
          message: 'Nimbus could not find a valid checkpoint for the current commit.',
        },
      ],
      warnings: [],
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint',
          ok: false,
          detail: 'No checkpoint is available for the current commit.',
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: 'Entire context cannot be resolved until a checkpoint is available.',
        },
      ],
      error: {
        code: 'checkpoint_unavailable',
        message: 'Nimbus could not find a valid checkpoint for the current commit.',
      },
    };
  }

  return {
    ...common,
    startability: 'intent_aware',
    contextMode: 'intent_aware',
    checkpointId: 'checkpoint_mock_ready',
    ready: true,
    capabilities: {
      canStart: true,
      canStartInBasicMode: true,
      canStartInIntentAwareMode: true,
      canReviewPolicy: true,
    },
    blockingIssues: [],
    warnings: [],
    checks: [
      {
        code: 'checkpoint',
        label: 'Checkpoint',
        ok: true,
        detail: 'A checkpoint is available for the current commit.',
      },
      {
        code: 'entire_context',
        label: 'Entire context',
        ok: true,
        detail: 'Entire context is available for the current checkpoint window.',
      },
    ],
  };
}

function createMockStartStages(preflight: StudioNewReviewPreflightResponse | null): StartStageState[] {
  const baseStages: StartStageState[] = [
    {
      stage: 'checkpoint',
      label: 'Checkpoint resolved',
      detail: 'Nimbus locked onto the current commit checkpoint.',
      state: 'completed',
    },
  ];

  if (preflight?.startability === 'intent_aware') {
    baseStages.push({
      stage: 'entire_context',
      label: 'Entire context loaded',
      detail: 'Nimbus found the available Entire context for this review.',
      state: 'completed',
    });
  }

  baseStages.push(
    {
      stage: 'workspace',
      label: 'Workspace prepared',
      detail: 'Nimbus prepared the launch workspace for the review session.',
      state: 'completed',
    },
    {
      stage: 'review_creation',
      label: 'Session creation simulated',
      detail: 'Mock mode stops here so you can inspect the UI without creating a real review.',
      state: 'completed',
    }
  );

  return baseStages;
}

function isTerminalPhase(phase: ReviewSessionResponse['phase']): boolean {
  return phase === 'completed' || phase === 'failed' || phase === 'cancelled';
}

function sessionRoute(session: Pick<ReviewSessionResponse, 'id'>): string {
  return `/sessions/${encodeURIComponent(session.id)}`;
}

function pickCurrentCommitSession(
  sessions: ReviewSessionResponse[],
  commitSha: string | null | undefined
): ReviewSessionResponse | null {
  if (!commitSha) {
    return null;
  }
  return (
    sessions
      .filter((session) => session.anchorCommitSha === commitSha)
      .slice()
      .sort((left, right) => {
        const terminalDelta = Number(isTerminalPhase(left.phase)) - Number(isTerminalPhase(right.phase));
        if (terminalDelta !== 0) {
          return terminalDelta;
        }
        return Date.parse(right.updatedAt) - Date.parse(left.updatedAt);
      })[0] ?? null
  );

