function isTerminalPhase(phase: ReviewSessionResponse['phase']): boolean {
  return phase === 'completed' || phase === 'failed' || phase === 'cancelled';
}

function sessionRoute(session: Pick<ReviewSessionResponse, 'id'>): string {
  return `/sessions/${encodeURIComponent(session.id)}`;
}

function pickCurrentCommitSession(
  sessions: ReviewSessionResponse[],
  commitSha: string | null | undefined
): ReviewSessionResponse | null {
  if (!commitSha) {
    return null;
  }
  return (
    sessions
      .filter((session) => session.anchorCommitSha === commitSha)
      .slice()
      .sort((left, right) => {
        const terminalDelta = Number(isTerminalPhase(left.phase)) - Number(isTerminalPhase(right.phase));
        if (terminalDelta !== 0) {
          return terminalDelta;
        }
        return Date.parse(right.updatedAt) - Date.parse(left.updatedAt);
      })[0] ?? null
  );
}

function resolveLaunchState(input: {
  loading: boolean;
  starting: boolean;
  hasRepoContext: boolean;
  preflight: StudioNewReviewPreflightResponse | null;
  error: string | null;
}): LaunchState {
  if (input.starting) {
    return 'starting';
  }
  if (input.loading && !input.preflight && !input.error) {
    return 'checking';
  }
  if (!input.hasRepoContext) {
    return 'blocked';
  }
  if (input.preflight?.startability === 'intent_aware') {
    return 'ready';
  }
  if (input.preflight?.startability === 'basic') {
    return 'basic';
  }
  if (input.preflight?.startability === 'blocked' || input.error) {
    return 'blocked';
  }
  return 'checking';
}

function launchStateLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Ready to review';
    case 'basic':
      return 'Basic mode fallback';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting review';
    default:
      return 'Checking current state';
  }
}

function launchHeadline(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Start a review session on the current commit.';
    case 'basic':
      return 'Start a basic review on the current commit.';
    case 'blocked':
      return 'Nimbus cannot start from this checkout.';
    case 'starting':
      return 'Starting the review session.';
    default:
      return 'Resolving the current repo and commit.';
  }
}

function launchDetail(state: LaunchState, input: {
  hasRepoContext: boolean;
  preflight: StudioNewReviewPreflightResponse | null;
  error: string | null;
}): string {
  if (state === 'ready') {
    return 'Nimbus will review the current commit with Entire-backed context and route directly into the new session.';
  }
  if (state === 'basic') {
    return 'Entire context is unavailable, but Nimbus can still review the current commit in basic diff/code-aware mode.';
  }
  if (state === 'starting') {
    return 'Nimbus is resolving context, creating the review, and opening the session.';
  }
  if (state === 'blocked') {
    if (!input.hasRepoContext) {
      return 'Open Review Studio from inside a git repository so Nimbus can resolve the current branch and commit.';
    }
    return (
      input.preflight?.blockingIssues[0]?.message ??
      input.preflight?.error?.message ??
      input.error ??
      'Studio could not resolve a startable review target from the current checkout.'
    );
  }
  return 'Nimbus is checking the repo, branch, and HEAD state before it decides whether to launch a new session or route to an existing one.';
}

function modeLabel(preflight: StudioNewReviewPreflightResponse | null): string {
  if (!preflight) {
    return 'Checking';
  }
  if (preflight.startability === 'intent_aware') {
    return 'Found';
  }
  if (preflight.startability === 'basic') {
    return 'Unavailable';
  }
  return 'Checking';
}

function preflightSignalLabel(state: LaunchState): string {
  switch (state) {
    case 'ready':
      return 'Ready';
    case 'basic':
      return 'Ready';
    case 'blocked':
      return 'Blocked';
    case 'starting':
      return 'Starting';
    default:
      return 'Checking';
  }
}

async function fetchJson(input: string): Promise<unknown> {
  const response = await fetch(input, { cache: 'no-store' });
  if (!response.ok) {
    throw new Error(`Request failed (${response.status})`);
  }
  return response.json();
}

