                                <span>{findingHeading(finding)}</span>
                              </li>
                            ))}
                          </ul>
                        </div>
                      ) : null}

                      <div className="pass-stream-note">
                        {passEvents.length
                          ? `${passEvents.length} streamed event(s) for this pass are shown in the live review console above.`
