  const [mockAdopted, setMockAdopted] = useState(false);
  const [mockMergedBack, setMockMergedBack] = useState(false);
  const effectiveMockState = mockStateOverride ?? baseMockState;
  const model = useMemo(() => createMockSessionModel(props.sessionId, effectiveMockState), [props.sessionId, effectiveMockState]);
  const [visibleCount, setVisibleCount] = useState(model.canStream ? 1 : model.events.length);

